import pandas as pd
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.ticker as mticker
import matplotlib.dates as mdates
from matplotlib.patches import FancyBboxPatch
import base64
from io import BytesIO
import warnings
warnings.filterwarnings('ignore')

# ── Palette ────────────────────────────────────────────────────────────────────
C_NAVY   = '#1a2e4a'
C_BLUE   = '#2563eb'
C_TEAL   = '#0891b2'
C_GREEN  = '#16a34a'
C_RED    = '#dc2626'
C_AMBER  = '#d97706'
C_GRAY   = '#6b7280'
C_LGRAY  = '#e5e7eb'
C_BG     = '#f8fafc'
C_WHITE  = '#ffffff'

plt.rcParams.update({
    'figure.facecolor': C_WHITE,
    'axes.facecolor':   C_BG,
    'axes.edgecolor':   C_LGRAY,
    'axes.labelcolor':  C_NAVY,
    'xtick.color':      C_GRAY,
    'ytick.color':      C_GRAY,
    'text.color':       C_NAVY,
    'grid.color':       C_LGRAY,
    'grid.linewidth':   0.7,
    'font.family':      'DejaVu Sans',
    'font.size':        10,
})

# ── Load & clean data ──────────────────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv')
df['Date'] = pd.to_datetime(df['Date'], format='%m/%d/%Y')
df = df.sort_values('Date').reset_index(drop=True)
df['Year'] = df['Date'].dt.year
df['Month'] = df['Date'].dt.month
df['YearMonth'] = df['Date'].dt.to_period('M')

# Daily returns
df['DailyReturn'] = df['Close'].pct_change()
df['DailyRange']  = df['High'] - df['Low']

# Rolling metrics (30-day window)
df['RollingVol30'] = df['DailyReturn'].rolling(30).std() * np.sqrt(252)
df['MA50']  = df['Close'].rolling(50).mean()
df['MA200'] = df['Close'].rolling(200).mean()

# Drawdown
df['CumMax'] = df['Close'].cummax()
df['Drawdown'] = (df['Close'] - df['CumMax']) / df['CumMax']

# ── KPIs ───────────────────────────────────────────────────────────────────────
first_close = df['Close'].iloc[0]
last_close  = df['Close'].iloc[-1]
first_date  = df['Date'].iloc[0]
last_date   = df['Date'].iloc[-1]

years_held    = (last_date - first_date).days / 365.25
cum_return    = (last_close / first_close - 1) * 100
cagr          = ((last_close / first_close) ** (1 / years_held) - 1) * 100
max_dd        = df['Drawdown'].min() * 100
avg_volume    = df['Volume'].mean()
ann_vol       = df['DailyReturn'].std() * np.sqrt(252) * 100

# Max drawdown details
dd_end_idx   = df['Drawdown'].idxmin()
dd_end_date  = df['Date'].iloc[dd_end_idx]
dd_peak_val  = df['CumMax'].iloc[dd_end_idx]
dd_trough_val= df['Close'].iloc[dd_end_idx]
peak_mask    = df['Close'][:dd_end_idx+1] == dd_peak_val
dd_peak_date = df['Date'][peak_mask].iloc[-1] if peak_mask.any() else None

# ATH / ATL
ath_idx   = df['Close'].idxmax()
atl_idx   = df['Close'].idxmin()
ath_price = df['Close'].iloc[ath_idx]
atl_price = df['Close'].iloc[atl_idx]
ath_date  = df['Date'].iloc[ath_idx]
atl_date  = df['Date'].iloc[atl_idx]

# Annual returns
annual = df.groupby('Year').agg(
    open_price=('Close','first'),
    close_price=('Close','last'),
    avg_vol=('Volume','mean'),
    high=('High','max'),
    low=('Low','min'),
).reset_index()
annual['AnnReturn'] = (annual['close_price'] / annual['open_price'] - 1) * 100

best_yr  = annual.loc[annual['AnnReturn'].idxmax()]
worst_yr = annual.loc[annual['AnnReturn'].idxmin()]

# Decade groupings
def decade(y):
    if y < 2010: return '2000s'
    elif y < 2020: return '2010s'
    else: return '2020s'

annual['Decade'] = annual['Year'].apply(decade)
decade_summary = annual.groupby('Decade').apply(
    lambda g: pd.Series({
        'start_price': g['open_price'].iloc[0],
        'end_price':   g['close_price'].iloc[-1],
        'avg_vol':     g['avg_vol'].mean(),
    })
).reset_index()
decade_summary['CumReturn'] = (decade_summary['end_price'] / decade_summary['start_price'] - 1) * 100
decade_summary['Years'] = decade_summary['Decade'].map({'2000s':10,'2010s':10,'2020s':6})
decade_summary['CAGR'] = ((decade_summary['end_price'] / decade_summary['start_price']) ** (1/decade_summary['Years']) - 1) * 100

# ── Helper: fig → base64 ───────────────────────────────────────────────────────
def fig_to_b64(fig, dpi=130):
    buf = BytesIO()
    fig.savefig(buf, format='png', dpi=dpi, bbox_inches='tight',
                facecolor=fig.get_facecolor())
    plt.close(fig)
    return base64.b64encode(buf.getvalue()).decode()

# ── Chart 1: Long-term price trend with MA lines ───────────────────────────────
def chart_price_trend():
    fig, ax = plt.subplots(figsize=(13, 5.5))
    ax.fill_between(df['Date'], df['Close'], alpha=0.08, color=C_BLUE)
    ax.plot(df['Date'], df['Close'], color=C_BLUE, lw=1.4, label='Close Price', zorder=3)
    ax.plot(df['Date'], df['MA50'],  color=C_AMBER, lw=1.0, ls='--', label='50-Day MA', zorder=2, alpha=0.85)
    ax.plot(df['Date'], df['MA200'], color=C_RED,   lw=1.0, ls='--', label='200-Day MA', zorder=2, alpha=0.85)

    # Annotate ATH
    ax.annotate(f'ATH ${ath_price:.2f}\n{ath_date.strftime("%b %Y")}',
                xy=(ath_date, ath_price), xytext=(ath_date - pd.Timedelta(days=900), ath_price*0.82),
                arrowprops=dict(arrowstyle='->', color=C_NAVY, lw=1.2),
                fontsize=8.5, color=C_NAVY,
                bbox=dict(boxstyle='round,pad=0.3', fc=C_WHITE, ec=C_LGRAY))

    # Crisis shading
    crises = [
        ('2000-03-01','2002-10-01', 'Dot-com bust'),
        ('2007-10-01','2009-03-01', 'GFC'),
        ('2020-02-15','2020-04-01', 'COVID'),
        ('2021-11-01','2023-01-01', 'Rate hike cycle'),
    ]
    y_min, y_max = ax.get_ylim()
    for s, e, lbl in crises:
        ax.axvspan(pd.Timestamp(s), pd.Timestamp(e), alpha=0.10, color=C_RED, zorder=0)
        mid = pd.Timestamp(s) + (pd.Timestamp(e)-pd.Timestamp(s))/2
        ax.text(mid, ax.get_ylim()[1]*0.97, lbl, ha='center', va='top',
                fontsize=7, color=C_RED, alpha=0.85)

    ax.set_title('NKE Closing Price (2000–2026) with 50 & 200-Day Moving Averages',
                 fontsize=12, fontweight='bold', pad=12)
    ax.set_ylabel('Adjusted Close (USD)', fontsize=10)
    ax.set_xlabel('')
    ax.xaxis.set_major_locator(mdates.YearLocator(2))
    ax.xaxis.set_major_formatter(mdates.DateFormatter('%Y'))
    ax.yaxis.set_major_formatter(mticker.FormatStrFormatter('$%.0f'))
    ax.legend(loc='upper left', fontsize=9, framealpha=0.9)
    ax.grid(True, axis='y', alpha=0.5)
    plt.xticks(rotation=45, ha='right')
    fig.tight_layout()
    return fig_to_b64(fig)

# ── Chart 2: Drawdown underwater chart ────────────────────────────────────────
def chart_drawdown():
    fig, ax = plt.subplots(figsize=(13, 3.8))
    ax.fill_between(df['Date'], df['Drawdown']*100, 0, color=C_RED, alpha=0.55)
    ax.plot(df['Date'], df['Drawdown']*100, color=C_RED, lw=0.8)
    ax.axhline(0, color=C_NAVY, lw=0.8, ls='--', alpha=0.5)

    ax.annotate(f'Max DD {max_dd:.1f}%\n{dd_end_date.strftime("%b %Y")}',
                xy=(dd_end_date, max_dd), xytext=(dd_end_date + pd.Timedelta(days=400), max_dd*0.6),
                arrowprops=dict(arrowstyle='->', color=C_NAVY, lw=1.1),
                fontsize=8.5, color=C_NAVY,
                bbox=dict(boxstyle='round,pad=0.3', fc=C_WHITE, ec=C_LGRAY))

    ax.set_title('Drawdown from Rolling Peak (%)', fontsize=11, fontweight='bold', pad=10)
    ax.set_ylabel('Drawdown (%)', fontsize=9)
    ax.xaxis.set_major_locator(mdates.YearLocator(2))
    ax.xaxis.set_major_formatter(mdates.DateFormatter('%Y'))
    ax.yaxis.set_major_formatter(mticker.FormatStrFormatter('%.0f%%'))
    ax.grid(True, axis='y', alpha=0.5)
    plt.xticks(rotation=45, ha='right')
    fig.tight_layout()
    return fig_to_b64(fig)

# ── Chart 3: Rolling 30-day annualised volatility ─────────────────────────────
def chart_volatility():
    fig, ax = plt.subplots(figsize=(13, 4.0))
    vol_pct = df['RollingVol30'] * 100
    ax.fill_between(df['Date'], vol_pct, alpha=0.18, color=C_TEAL)
    ax.plot(df['Date'], vol_pct, color=C_TEAL, lw=1.2)
    ax.axhline(ann_vol, color=C_NAVY, lw=1.0, ls='--', alpha=0.7,
               label=f'Full-period avg {ann_vol:.1f}%')

    # Annotate spikes
    spikes = [
        ('2008-09-01', '2008-10-01', 'GFC spike'),
        ('2020-02-15', '2020-04-01', 'COVID spike'),
    ]
    for s, e, lbl in spikes:
        ax.axvspan(pd.Timestamp(s), pd.Timestamp(e), alpha=0.15, color=C_AMBER)
        mid = pd.Timestamp(s) + (pd.Timestamp(e)-pd.Timestamp(s))/2
        ax.text(mid, vol_pct.max()*0.95, lbl, ha='center', va='top',
                fontsize=7.5, color=C_AMBER)

    ax.set_title('30-Day Rolling Annualised Volatility (%)', fontsize=11, fontweight='bold', pad=10)
    ax.set_ylabel('Ann. Volatility (%)', fontsize=9)
    ax.xaxis.set_major_locator(mdates.YearLocator(2))
    ax.xaxis.set_major_formatter(mdates.DateFormatter('%Y'))
    ax.yaxis.set_major_formatter(mticker.FormatStrFormatter('%.0f%%'))
    ax.legend(fontsize=9, framealpha=0.9)
    ax.grid(True, axis='y', alpha=0.5)
    plt.xticks(rotation=45, ha='right')
    fig.tight_layout()
    return fig_to_b64(fig)

# ── Chart 4: Daily price range (High-Low) monthly avg ─────────────────────────
def chart_daily_range():
    monthly_range = df.groupby('YearMonth')['DailyRange'].mean().reset_index()
    monthly_range['Date'] = monthly_range['YearMonth'].dt.to_timestamp()
    fig, ax = plt.subplots(figsize=(13, 3.8))
    ax.fill_between(monthly_range['Date'], monthly_range['DailyRange'], alpha=0.25, color=C_BLUE)
    ax.plot(monthly_range['Date'], monthly_range['DailyRange'], color=C_BLUE, lw=1.1)
    ax.set_title('Average Daily Price Range (High–Low), Monthly', fontsize=11, fontweight='bold', pad=10)
    ax.set_ylabel('Daily Range (USD)', fontsize=9)
    ax.xaxis.set_major_locator(mdates.YearLocator(2))
    ax.xaxis.set_major_formatter(mdates.DateFormatter('%Y'))
    ax.yaxis.set_major_formatter(mticker.FormatStrFormatter('$%.2f'))
    ax.grid(True, axis='y', alpha=0.5)
    plt.xticks(rotation=45, ha='right')
    fig.tight_layout()
    return fig_to_b64(fig)

# ── Chart 5: Volume + price dual axis ─────────────────────────────────────────
def chart_volume():
    monthly_vol   = df.groupby('YearMonth')['Volume'].mean().reset_index()
    monthly_close = df.groupby('YearMonth')['Close'].last().reset_index()
    monthly_vol['Date']   = monthly_vol['YearMonth'].dt.to_timestamp()
    monthly_close['Date'] = monthly_close['YearMonth'].dt.to_timestamp()

    fig, ax1 = plt.subplots(figsize=(13, 4.5))
    ax2 = ax1.twinx()

    ax1.bar(monthly_vol['Date'], monthly_vol['Volume']/1e6, width=25,
            color=C_TEAL, alpha=0.55, label='Avg Daily Volume (M)')
    ax2.plot(monthly_close['Date'], monthly_close['Close'], color=C_BLUE,
             lw=1.3, label='Close Price', zorder=3)

    # Key events
    events = [
        ('2009-03-09', 'GFC bottom'),
        ('2020-03-23', 'COVID low'),
        ('2021-11-05', '52-wk high'),
    ]
    for dt, lbl in events:
        ax1.axvline(pd.Timestamp(dt), color=C_RED, lw=0.9, ls='--', alpha=0.6)
        ax1.text(pd.Timestamp(dt), monthly_vol['Volume'].max()/1e6*0.9, lbl,
                 ha='left', va='top', fontsize=7, color=C_RED, rotation=90)

    ax1.set_title('Monthly Average Daily Volume vs. Closing Price', fontsize=11, fontweight='bold', pad=10)
    ax1.set_ylabel('Avg Daily Volume (millions)', fontsize=9, color=C_TEAL)
    ax2.set_ylabel('Close Price (USD)', fontsize=9, color=C_BLUE)
    ax1.xaxis.set_major_locator(mdates.YearLocator(2))
    ax1.xaxis.set_major_formatter(mdates.DateFormatter('%Y'))
    ax1.tick_params(axis='y', labelcolor=C_TEAL)
    ax2.tick_params(axis='y', labelcolor=C_BLUE)
    lines1, labels1 = ax1.get_legend_handles_labels()
    lines2, labels2 = ax2.get_legend_handles_labels()
    ax1.legend(lines1+lines2, labels1+labels2, loc='upper left', fontsize=9)
    ax1.grid(True, axis='y', alpha=0.4)
    plt.xticks(rotation=45, ha='right')
    fig.tight_layout()
    return fig_to_b64(fig)

# ── Chart 6: Annual returns bar chart ─────────────────────────────────────────
def chart_annual_returns():
    fig, ax = plt.subplots(figsize=(13, 4.5))
    colors = [C_GREEN if r >= 0 else C_RED for r in annual['AnnReturn']]
    bars = ax.bar(annual['Year'], annual['AnnReturn'], color=colors, width=0.75, edgecolor=C_WHITE, lw=0.5)
    ax.axhline(0, color=C_NAVY, lw=0.9)

    # Label best/worst
    for _, row in annual[['Year','AnnReturn']].iterrows():
        if abs(row['AnnReturn']) > 35:
            ax.text(row['Year'], row['AnnReturn'] + (2 if row['AnnReturn']>0 else -2),
                    f"{row['AnnReturn']:.0f}%", ha='center', va='bottom' if row['AnnReturn']>0 else 'top',
                    fontsize=7.5, color=C_NAVY, fontweight='bold')

    ax.set_title('Annual Return by Year (%)', fontsize=11, fontweight='bold', pad=10)
    ax.set_ylabel('Annual Return (%)', fontsize=9)
    ax.set_xlabel('Year', fontsize=9)
    ax.yaxis.set_major_formatter(mticker.FormatStrFormatter('%.0f%%'))
    ax.set_xticks(annual['Year'])
    ax.set_xticklabels(annual['Year'], rotation=45, ha='right', fontsize=8)
    ax.grid(True, axis='y', alpha=0.5)
    fig.tight_layout()
    return fig_to_b64(fig)

# ── Chart 7: Growth of $10,000 ─────────────────────────────────────────────────
def chart_growth():
    inv = (df['Close'] / df['Close'].iloc[0]) * 10000
    fig, ax = plt.subplots(figsize=(13, 4.5))
    ax.fill_between(df['Date'], inv, 10000, where=(inv>=10000), alpha=0.12, color=C_GREEN)
    ax.fill_between(df['Date'], inv, 10000, where=(inv<10000),  alpha=0.15, color=C_RED)
    ax.plot(df['Date'], inv, color=C_BLUE, lw=1.5)
    ax.axhline(10000, color=C_GRAY, lw=0.8, ls='--', alpha=0.7, label='Initial $10,000')
    final = inv.iloc[-1]
    ax.annotate(f'${final:,.0f}\n({last_date.strftime("%b %Y")})',
                xy=(last_date, final),
                xytext=(last_date - pd.Timedelta(days=1800), final*0.82),
                arrowprops=dict(arrowstyle='->', color=C_NAVY, lw=1.1),
                fontsize=9, color=C_NAVY,
                bbox=dict(boxstyle='round,pad=0.3', fc=C_WHITE, ec=C_LGRAY))
    ax.set_title('Growth of $10,000 Invested at Start of 2000', fontsize=11, fontweight='bold', pad=10)
    ax.set_ylabel('Portfolio Value (USD)', fontsize=9)
    ax.xaxis.set_major_locator(mdates.YearLocator(2))
    ax.xaxis.set_major_formatter(mdates.DateFormatter('%Y'))
    ax.yaxis.set_major_formatter(mticker.FuncFormatter(lambda x,_: f'${x:,.0f}'))
    ax.legend(fontsize=9)
    ax.grid(True, axis='y', alpha=0.5)
    plt.xticks(rotation=45, ha='right')
    fig.tight_layout()
    return fig_to_b64(fig)

